/**
 * Verifica si una cadena es un palíndromo.
 *
 * @param {string} cadena La cadena a verificar.
 * @returns {boolean} True si la cadena es un palíndromo, false en caso contrario.
 */
function esPalindromo(cadena) {
  if (typeof cadena !== 'string') {
    return false; // Manejar casos inválidos: no es una cadena.
  }

  const cadenaMinuscula = cadena.toLowerCase().replace(/\s/g, ''); // Convertir a minúsculas y eliminar espacios.
  const reversedCadena = cadenaMinuscula.split('').reverse().join(''); // Invertir la cadena.

  return cadenaMinuscula === reversedCadena; // Comparar la cadena original con la invertida.
}
